// Demo: Code-to-Docs Extraction — doc coverage over 1 symbols
var syms=[];for(var i=0;i<1;i++){syms.push({name:'fn'+i,doc:((i*7+1)%3!==0)});}
var covered=syms.filter(function(s){return s.doc;}).length;
console.log('technique: Code-to-Docs Extraction');console.log('symbols: '+syms.length+', documented: '+covered);
console.log('coverage: '+(100*covered/syms.length).toFixed(1)+'%');
console.log('undocumented: '+syms.filter(function(s){return !s.doc;}).slice(0,5).map(function(s){return s.name;}).join(', '));

