// Demo: Diagram Generation — stale reference detection
var code=['fnA','fnB','fnC'];var docs=['fnA','fnB','fnOld'];
var stale=docs.filter(function(d){return code.indexOf(d)<0;});
console.log('technique: Diagram Generation');console.log('code symbols: '+code.join(', '));
console.log('doc references: '+docs.join(', '));
console.log(stale.length?'STALE: '+stale.join(', ')+' — update or remove':'all references fresh');

// Demo: Changelog Compilation — changelog grouping from 24 commits
var types={};for(var i=0;i<24;i++){var t=['feat','fix','docs','chore'][(i*13+4)%4];types[t]=(types[t]||0)+1;}
console.log('technique: Changelog Compilation');
Object.keys(types).sort().forEach(function(t){console.log(t+': '+types[t]+' commits');});

